import {CREATURES,STAGE_NAMES,MILESTONES,growthDay} from './growth.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
// Explicit crop rectangles keep AI atlas gutters and neighboring pixels out of the app.
const SPRITE_RECTS=[
 [80,145,150,168],[350,145,165,168],[620,95,170,218],[875,125,210,188],[1135,85,255,228],
 [40,385,235,190],[310,345,245,232],[580,335,250,242],[840,335,275,242],[1130,340,260,237],
 [40,590,245,240],[305,590,257,240],[590,590,230,240],[830,610,280,220],[1120,580,280,250],
 [35,832,250,250],[290,832,265,250],[555,832,290,250],[866,845,244,240],[1115,840,285,245]
];
export function creatureArt(id,stage=0){const c=CREATURES[id]||CREATURES.egg;
 const [x,y,w,h]=SPRITE_RECTS[c.sprite??0],size=Math.max(w,h)+32;
 return `<svg class="creature pixel-pet" viewBox="0 0 ${size} ${size}" role="img" aria-label="${esc(c.name)}"><svg x="${(size-w)/2}" y="${(size-h)/2}" width="${w}" height="${h}" viewBox="${x} ${y} ${w} ${h}" overflow="hidden"><image href="./characters.png" width="1402" height="1122"/></svg></svg>`;
}
export function growthNotice(g){return `<button class="growth-shortcut" data-tab="growth">${g?.stage===4?'育った子が図鑑に仲間入り！':g?.stage?'おてつだいと一緒に、すくすく成長中':'タマゴが待っているよ。最初のおてつだいで生まれるよ。'} <span>そだてる →</span></button>`}
export function growthContent(g,role,records,more,event,loaded){const stage=g?.stage||0,c=CREATURES[g?.character||'egg'],day=growthDay(g),next=MILESTONES.find(m=>m.stage===stage+1),celebrate=event&&Date.now()-event.at<5000;return `<div class="section-head"><div><h2>きみと育つ、小さなともだち</h2><p>どんな姿になるかは、育ってからのお楽しみ。</p></div></div><section class="growth-hero ${celebrate?'celebrate':''} ${celebrate&&stage===4?'final-celebration':''}"><div class="growth-scene">${creatureArt(g?.character||'egg',stage)}${celebrate?'<span class="growth-stars" aria-hidden="true">✦　✧　✦</span>':''}</div><div class="growth-details"><span class="pill">${STAGE_NAMES[stage]}${day?' · '+day+'日目':''}</span><h2>${c.name}</h2><p role="status">${celebrate?(event.evolved?'なんだか様子が違う……新しい姿になったよ！':'おてつだい、ありがとう！ 成長 +10'):stage===0?'最初のおてつだいを、おうちの人がOKすると生まれるよ。':stage===4?'りっぱに育ったね！図鑑に思い出を残したよ。':'休んでも大丈夫。きみのペースで育てよう。'}</p>${stage?`<div class="growth-total">${g.points}<small> 成長ポイント</small></div><p>おてつだい ${g.count}回</p>`:''}${next?`<div class="growth-target"><label>次の成長まで <strong>${Math.min(g.points,next.points)} / ${next.points} pt</strong><progress max="${next.points}" value="${Math.min(g.points,next.points)}"></progress></label><p>${day>=next.day?'日数の条件はクリア！':next.day+'日目まで、あと'+(next.day-day)+'日'} · ${g.points>=next.points?'ポイントの条件はクリア！':'あと'+(next.points-g.points)+'成長ポイント'}</p>${day>=next.day&&g.points>=next.points?'<p>なんだか様子が違う……おうちの人の画面で成長を確かめよう。</p>':''}</div>`:''}${stage===4?(role==='parent'?'<button class="primary" data-action="nextEgg">次のタマゴを迎える</button>':'<p>次のタマゴは、おうちの人に迎えてもらおう。</p>'):''}</div></section><div class="notice">おてつだいを送ったあとは確認待ち。おうちの人がOKすると成長10ポイント！ ごほうびと交換しても減らないよ。${role==='parent'?' 日数による進化は、この画面を開いている間や再度開いたときに確認します。':''}</div><div class="section-head"><div><h2>ともだち図鑑</h2><p>同じ姿の子も、一匹ずつ思い出に。</p></div></div><div class="growth-collection">${records.map(r=>`<article class="growth-memory">${creatureArt(r.characterId,4)}<div><h3>${esc(r.name)}</h3><p>${esc(r.startDate)} → ${esc(r.finalDate)}</p><small>${r.days}日間 · おてつだい ${r.count}回 · ${r.points}成長pt</small></div></article>`).join('')||`<div class="empty">${loaded?'最終進化したら、ここに仲間入りするよ。':'図鑑を読みこんでいます…'}</div>`}</div>${more?'<button data-action="growthMore">前の思い出も見る</button>':''}`}
